      "text": "एक पड़ेगा कितने का एक meter कितने का पड़ता है?"
    },
    {
      "i": 31,
      "speaker": "bot",
      "text": "आप इसकी price seller से discuss कर सकते हैं।"
    },
    {
      "i": 32,
      "speaker": "bot",
      "text": "वो आपको best rates देंगे।"
    },
    {
      "i": 33,
      "speaker": "bot",
      "text": "पर process करने के लिए quantity बताना जरूरी है।"
    },
    {
      "i": 34,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 35,
      "speaker": "bot",
      "text": "तो please बता दीजिए आपको कितनी meter quantity की जरूरत है?"
    },
    {
      "i": 36,
      "speaker": "caller",
      "text": "पांच सौ अस्सी।"
    },
    {
      "i": 37,
      "speaker": "bot",
      "text": "ठीक है 580 meter।"
    },
    {
      "i": 38,
      "speaker": "bot",
      "text": "अब चलिए width के बारे में बात कर लेते हैं।"
    },
    {
      "i": 39,
      "speaker": "bot",
      "text": "आपको एक inch 25 mm चाहिए या कुछ और?"
    },
    {
      "i": 40,
      "speaker": "caller",
      "text": "नहीं मुझे delivery का पहले पता करना है delivery आप कब तक करते हैं?"
    },
    {
      "i": 41,
      "speaker": "bot",
      "text": "delivery के बारे में आप सीधे seller से discuss कर सकते हैं।"
    },
    {
      "i": 42,
      "speaker": "bot",
      "text": "वो आपको सही समय बता देंगे।"
    },
    {
      "i": 43,
      "speaker": "bot",
      "text": "बस।"
    }
  ]
